# Headless smoke test of the jamovi analysis classes. Run from the module root:  Rscript tests/smoke.R
# Also run it in jamovi's own R with the bundled libraries (see PLAN.md).
suppressMessages({library(jmvcore); library(R6); library(ggplot2)})
for (f in c("R/00jmv.R", "R/engine_ps.R", "R/engine_weight.R", "R/engine_balance.R", "R/engine_ebal.R", "R/engine_match.R", "R/engine_compare.R", "R/engine_sens.R", "R/common.R", "R/guide.R", list.files("R", "[.]h[.]R$", full.names = TRUE),
            list.files("R", "[.]b[.]R$", full.names = TRUE))) source(f)
sim <- read.csv("data/sim_confounded.csv"); ll <- read.csv("data/lalonde.csv"); ov <- read.csv("data/sim_overlap.csv")
ll$race <- factor(ll$race)
hid <- read.csv("data/sim_hidden.csv")
bad <- 0
run <- function(label, fn, data, tab, ...) {
    a <- list(...)
    fm <- formals(fn)
    for (n in setdiff(names(fm)[vapply(fm, function(z) identical(z, quote(expr = )), logical(1))], c("data", names(a)))) a[n] <- list(NULL)
    r <- tryCatch({ res <- do.call(fn, c(list(data = data), a)); n <- nrow(as.data.frame(res[[tab]])); if (n < 1) stop("empty table"); "ok" },
                  error = function(e) paste("ERROR:", conditionMessage(e)))
    expect_err <- grepl("^EXPECT", label)
    cat(sprintf("%-52s %s", label, if (expect_err) sub("^ERROR: ", "message: ", r) else r), "\n", sep = "")
    if (!expect_err && r != "ok") bad <<- bad + 1
}
cv <- c("x1", "x2", "x3")
for (l in c("logit", "probit")) run(paste("psmodel", l), psmodel, sim, "coef", treat = "treat", covs = cv, link = l)
run("psmodel lalonde + notes", psmodel, ll, "coef", treat = "treat", covs = c("age", "educ", "race", "married", "nodegree", "re74", "re75"), showHelp = TRUE, showGuide = TRUE)
for (t in c("minmax", "crump", "custom")) run(paste("psmodel trim", t), psmodel, ov, "summary", treat = "treat", covs = c("x1", "x2"), trim = t, trimLo = 0.1, trimHi = 0.9)
for (e in c("all", "ate", "att", "atc")) run(paste("wtest", e), wtest, sim, "effects", outcome = "y", treat = "treat", covs = cv, estimand = e)
run("wtest ATO, all estimators (IPWRA skipped)", wtest, sim, "effects", outcome = "y", treat = "treat", covs = cv, estimand = "ato", doIpwra = TRUE, showWeights = TRUE)
run("wtest CBPS, all estimands", wtest, sim, "effects", outcome = "y", treat = "treat", covs = cv, link = "cbps", showWeights = TRUE)
run("wtest CBPS with ATO (falls back to the logit score)", wtest, sim, "effects", outcome = "y", treat = "treat", covs = cv, link = "cbps", estimand = "ato")
run("EXPECT ATO with IPWRA only", wtest, sim, "effects", outcome = "y", treat = "treat", covs = cv, estimand = "ato", doRa = FALSE, doIpw = FALSE, doAipw = FALSE, doIpwra = TRUE)
for (e in c("ato", "ate", "att", "atc")) run(paste("balance CBPS and overlap weights,", e), balance, sim, "bal", treat = "treat", covs = cv, adjust = "ipw", estimand = e, link = "cbps")
run("wtest probit + extra + weights", wtest, transform(sim, w = runif(nrow(sim), 0.5, 2), x4 = x1^2), "effects", outcome = "y", treat = "treat", covs = cv, extra = "x4",
    weights = "w", link = "probit", showPom = TRUE)
set.seed(1); sim$g <- factor(sample(1:60, nrow(sim), TRUE))
run("wtest cluster", wtest, sim, "effects", outcome = "y", treat = "treat", covs = cv, cluster = "g")
run("wtest lalonde nominal covariate, notes", wtest, ll, "effects", outcome = "re78", treat = "treat", covs = c("age", "educ", "race", "married", "nodegree", "re74", "re75"),
    showHelp = TRUE, showGuide = TRUE)
run("wtest trimming", wtest, ov, "effects", outcome = "y", treat = "treat", covs = c("x1", "x2"), trim = "crump")
sim2 <- sim; sim2$tf <- factor(ifelse(sim2$treat == 1, "yes", "no"))
run("wtest factor treatment", wtest, sim2, "effects", outcome = "y", treat = "tf", covs = cv)
run("EXPECT non-binary treatment", wtest, transform(sim, tt = x1), "effects", outcome = "y", treat = "tt", covs = c("x2", "x3"))
run("EXPECT no estimator ticked", wtest, sim, "effects", outcome = "y", treat = "treat", covs = cv, doRa = FALSE, doIpw = FALSE, doAipw = FALSE, doIpwra = FALSE)
sep <- sim; sep$perfect <- as.numeric(sep$treat == 1)
run("EXPECT perfect predictor", psmodel, sep, "coef", treat = "treat", covs = c("x1", "perfect"))
col <- sim; col$x1b <- col$x1 * 2
run("EXPECT collinear covariates", psmodel, col, "coef", treat = "treat", covs = c("x1", "x1b"))
run("EXPECT variable in two roles", wtest, sim, "effects", outcome = "y", treat = "treat", covs = c("y", "x1"))
run("EXPECT trimming empties a group", wtest, ov, "effects", outcome = "y", treat = "treat", covs = c("x1", "x2"), trim = "custom", trimLo = 0.4, trimHi = 0.41)
cl <- c("age", "educ", "race", "married", "nodegree", "re74", "re75")
for (a in c("none", "ipw", "ebal")) for (e in c("ate", "att", "atc"))
    run(paste("balance lalonde", a, e), balance, ll, "bal", treat = "treat", covs = cl, adjust = a, estimand = e, showHelp = TRUE, showGuide = TRUE)
run("balance probit + sampling weights", balance, transform(sim, w = runif(nrow(sim), 0.5, 2)), "bal", treat = "treat", covs = cv, weights = "w", link = "probit", denom = "pooled", stdBinary = FALSE)
run("balance weights variable", balance, transform(sim, wv = runif(nrow(sim), 0, 2)), "bal", treat = "treat", covs = cv, adjust = "var", adjW = "wv")
run("balance ebal 3 moments", balance, sim, "bal", treat = "treat", covs = cv, adjust = "ebal", moments = "m3", estimand = "att")
for (e in c("ate", "att", "atc")) for (m in c("m1", "m2"))
    run(paste("ebal sim", e, m), ebal, sim, "effects", outcome = "y", treat = "treat", covs = cv, estimand = e, moments = m, showPom = TRUE)
run("ebal lalonde att + notes", ebal, ll, "effects", outcome = "re78", treat = "treat", covs = cl, estimand = "att", showHelp = TRUE, showGuide = TRUE)
run("ebal cluster + sampling weights", ebal, transform(sim, w = runif(nrow(sim), 0.5, 2)), "effects", outcome = "y", treat = "treat", covs = cv, weights = "w", cluster = "g")
run("EXPECT balance weights variable missing", balance, sim, "bal", treat = "treat", covs = cv, adjust = "var")
run("EXPECT balance negative weights", balance, transform(sim, wv = x1), "bal", treat = "treat", covs = c("x2", "x3"), adjust = "var", adjW = "wv")
run("EXPECT ebal infeasible moments (lalonde ATC, 2 moments)", ebal, ll, "effects", outcome = "re78", treat = "treat", covs = cl, estimand = "atc", moments = "m2")
run("EXPECT ebal non-binary treatment", ebal, transform(sim, tt = x1), "effects", outcome = "y", treat = "tt", covs = c("x2", "x3"))
for (e in c("ate", "att", "atc")) for (m in c("maha", "ivar", "eucl"))
    run(paste("nnmatch sim", e, m), nnmatch, sim, "effects", outcome = "y", treat = "treat", covs = cv, estimand = e, metric = m, k = 2)
run("nnmatch bias adjustment + notes", nnmatch, sim, "effects", outcome = "y", treat = "treat", covs = cv, estimand = "att", biasadj = TRUE, showHelp = TRUE, showGuide = TRUE)
run("nnmatch adjvars", nnmatch, transform(sim, x4 = x1^2), "effects", outcome = "y", treat = "treat", covs = cv, adjvars = "x4", biasadj = TRUE, k = 3)
run("nnmatch lalonde ties", nnmatch, ll, "effects", outcome = "re78", treat = "treat", covs = cl, estimand = "att", k = 3)
run("nnmatch lalonde exact + caliper", nnmatch, ll, "effects", outcome = "re78", treat = "treat", covs = c("age", "educ", "re74", "re75"), exact = c("married", "nodegree"), caliper = 5, estimand = "att")
run("nnmatch lalonde ate nominal", nnmatch, ll, "effects", outcome = "re78", treat = "treat", covs = cl, estimand = "ate", biasadj = TRUE)
run("EXPECT nnmatch caliper too small", nnmatch, sim, "effects", outcome = "y", treat = "treat", covs = cv, caliper = 1e-9)
run("EXPECT nnmatch collinear covariates", nnmatch, col, "effects", outcome = "y", treat = "treat", covs = c("x1", "x1b"))
for (e in c("ate", "att", "atc")) run(paste("matchcmp sim", e), matchcmp, sim, "est", outcome = "y", treat = "treat", covs = cv, estimand = e)
run("matchcmp lalonde + notes", matchcmp, ll, "est", outcome = "re78", treat = "treat", covs = cl, estimand = "att", moments = "m2", showHelp = TRUE, showGuide = TRUE)
run("matchcmp lalonde atc (ebal infeasible with 2 moments)", matchcmp, ll, "est", outcome = "re78", treat = "treat", covs = cl, estimand = "atc", moments = "m2")
run("matchcmp subset of methods", matchcmp, sim, "est", outcome = "y", treat = "treat", covs = cv, doNaive = FALSE, doRa = FALSE, doAipw = FALSE, doIpwra = FALSE, k = 3, biasadj = FALSE)
run("sensobs data att", sensobs, hid, "evalue", outcome = "y", treat = "treat", covs = c("x1", "x2"), estimand = "att", showHelp = TRUE, showGuide = TRUE)
run("sensobs data ate k=2", sensobs, hid, "rosen", outcome = "y", treat = "treat", covs = c("x1", "x2"), estimand = "ate", k = 2, gammaMax = 5)
for (ty in c("smd", "rr", "or_rare", "or_common", "hr_rare", "hr_common")) run(paste("sensobs manual", ty), sensobs, sim, "evalue", outcome = "y", mode = "manual", mType = ty, mEst = 1.6, mLo = 1.2, mHi = 2.1)
run("sensobs manual ci includes null", sensobs, sim, "evalue", outcome = "y", mode = "manual", mType = "rr", mEst = 1.2, mLo = 0.8, mHi = 1.8)
run("EXPECT sensobs manual negative ratio", sensobs, sim, "evalue", outcome = "y", mode = "manual", mType = "rr", mEst = -1, mLo = 0.5, mHi = 2)
run("EXPECT sensobs data without covariates", sensobs, hid, "evalue", outcome = "y", treat = "treat", covs = character(0))
run("ebal all estimands", ebal, sim, "effects", outcome = "y", treat = "treat", covs = cv, showPom = TRUE)
run("ebal all, lalonde 2 moments (ATC infeasible, noted)", ebal, ll, "effects", outcome = "re78", treat = "treat", covs = cl, moments = "m2")
run("nnmatch all estimands", nnmatch, sim, "effects", outcome = "y", treat = "treat", covs = cv, k = 2, biasadj = TRUE)
run("nnmatch all, lalonde ties", nnmatch, ll, "effects", outcome = "re78", treat = "treat", covs = cl)
run("matchcmp all estimands, lalonde", matchcmp, ll, "est", outcome = "re78", treat = "treat", covs = cl, moments = "m2")
cat(if (bad == 0) "\nAll matching, weighting and balance analyses ran.\n" else sprintf("\n%d run(s) failed.\n", bad))
if (bad > 0) quit(status = 1)
